"""Planted probe chains, prose variants and the real-text benchmark."""
import numpy as np
import re as _re_inf
from platypus.common import (
    _set_global,
)
from platypus.config import (
    PILE_DOMAINS,
)
from platypus.inference.units import (
    _INF_REL, _INF_SYL, _UNITS, _UnitName, _UnitTrip, _units_on,
)

_INF={'probes':None}
def _inf_phrase(t): return t.split('{a} ')[1].split(' {b}')[0]
def inf_probes(cfg):
    """the probe chains (cached): list of dicts {names:[A,B,C(,D)], rels:[phrase...], doms:[dX,dY(,dZ)], facts:[(dom, sentence)]}"""
    if _INF['probes'] is not None: return _INF['probes']
    if _units_on(cfg):                                                          # cg20s: RULE-FREE: names and facts come from the learned lexicon
        _set_global('_INF_NAME',_UnitName()); _set_global('_INF_TRIP',_UnitTrip()); _UNITS['on']=True
    elif int(getattr(cfg,'inf_name_strict',0)):                                 # cg20i: a name never touches a letter or a non-ASCII byte (no 'Katar' out of 'Katariny')
        _set_global('_INF_NAME',_re_inf.compile(rb'(?<![A-Za-z\x80-\xff])[A-Z][a-z]{3,11}(?![A-Za-z\x80-\xff])'))
    nd_=len(PILE_DOMAINS); rs_=np.random.RandomState(int(cfg.seed)+2020); used=set(); ch=[]
    def nm():
        while True:
            n_=''.join(rs_.choice(_INF_SYL,rs_.randint(2,4))); n_=n_[0].upper()+n_[1:]
            if int(getattr(cfg,'inf_probe_rare',0)) and not any(ch_ in n_.lower() for ch_ in 'qxz'): continue   # cg20j: invented names carry q, x or z (no collision with real words)
            if 5<=len(n_)<=10 and n_ not in used: used.add(n_); return n_
    for k_ in range(int(cfg.inf_probes)):
        h_=3 if rs_.rand()<float(cfg.inf_hops3) else 2; n_=[nm() for _ in range(h_+1)]; tp_=[_INF_REL[rs_.randint(len(_INF_REL))] for _ in range(h_)]
        ds_=[int(rs_.randint(nd_))]
        for _ in range(h_-1): ds_.append(int((ds_[-1]+1+rs_.randint(nd_-1))%nd_))   # consecutive facts in DIFFERENT domains
        ch.append({'names':n_,'rels':[_inf_phrase(t_) for t_ in tp_],'doms':ds_,'facts':[(ds_[i_],tp_[i_].format(a=n_[i_],b=n_[i_+1])) for i_ in range(h_)],'api':False,'tp':tp_})
    uf_=float(getattr(cfg,'inf_upd_frac',0.0))
    rsu_=np.random.RandomState(int(cfg.seed)+3030)
    for c_ in ch:                                                           # BELIEF REVISION probes (two-hop chains): from pass 2 the first fact changes
        if uf_<=0 or len(c_['names'])!=3 or rsu_.rand()>=uf_: continue
        A_=c_['names'][0]; t0_,t1_=c_['tp'][0],c_['tp'][1]
        if rsu_.rand()<2/3:                                                 #   TRUE UPDATE: 'A r0 B' becomes 'A r0 B2' (planted as often as any fact), plus 'B2 r1 C2'
            B2_,C2_=nm(),nm(); c_['upd']={'type':'true','B2':B2_,'C2':C2_,'new':[(c_['doms'][0],t0_.format(a=A_,b=B2_)),(c_['doms'][1],t1_.format(a=B2_,b=C2_))]}
        else:                                                               #   NOISE: one single contradicting sentence 'A r0 B3'; the old fact stays
            B3_=nm(); c_['upd']={'type':'noise','B3':B3_,'new':[(c_['doms'][0],t0_.format(a=A_,b=B3_))]}
    kf_=float(getattr(cfg,'inf_probe_known',0.0))
    if kf_>0 and not cfg.inf_probe_file:                                        # KNOWN-WORD PROBES: the chain ends in a real place name the trunk already knows
        KP_=['Lisbon','Porto','Seville','Valencia','Bilbao','Lyon','Toulouse','Marseille','Bordeaux','Nantes','Geneva','Zurich','Basel','Vienna','Salzburg',
             'Prague','Krakow','Warsaw','Gdansk','Munich','Hamburg','Dresden','Leipzig','Cologne','Bremen','Antwerp','Ghent','Bruges','Utrecht','Leiden',
             'Bergen','Oslo','Uppsala','Malmo','Aarhus','Turku','Tallinn','Riga','Vilnius','Dublin','Cork','Galway','Glasgow','Leeds','York','Bristol',
             'Oxford','Cambridge','Florence','Venice','Verona','Naples','Turin','Genoa','Bologna','Athens','Sofia','Zagreb','Ljubljana','Budapest']
        rsk_=np.random.RandomState(int(cfg.seed)+8080); rsk_.shuffle(KP_); kk_=0; kn0_=[]
        for c_ in ch:
            if len(c_['names'])!=3 or c_.get('upd') or c_.get('var') or rsk_.rand()>=kf_ or kk_>=len(KP_): continue
            C0_,C1_=c_['names'][2],KP_[kk_]; kk_+=1; c_['names'][2]=C1_; c_['known']=True; kn0_.append(C1_)
            c_['facts']=[(d_,t_.replace(C0_,C1_)) for d_,t_ in c_['facts']]
        _INF['known_c']=kn0_
    vf_=float(getattr(cfg,'inf_probe_variant',0.0))
    if vf_>0 and not cfg.inf_probe_file:                                        # VARIANT BRIDGES: 'Galbriqui ... ' in one fact, 'Galbriqu ...' in the other -
        rsv_=np.random.RandomState(int(cfg.seed)+7070)                          #   an exact-name linker cannot chain them; a fuzzy one can
        for c_ in ch:
            if len(c_['names'])!=3 or c_.get('upd') or rsv_.rand()>=vf_: continue
            B_=c_['names'][1]; V_=B_[:-1] if len(B_)>=6 else B_+'a'
            if V_ in used: continue
            used.add(V_); c_['var']=V_; d1_,s1_=c_['facts'][1]; d0_,s0_=c_['facts'][0]
            kt_=int(getattr(cfg,'inf_probe_variant_k',0)); kc_=int(getattr(cfg,'inf_probe_variant_ctx',0))
            if kt_>0: c_['vtypo']=[(d1_,s1_.replace(B_,V_))]*kt_                 #   RARE TYPO: the fact keeps its spelling; the typo appears k times
            else:
                c_['facts'][1]=(d1_,s1_.replace(B_,V_))
                if kc_>0: c_['vtypo']=[(d0_,s0_.replace(B_,V_))]*kc_             #   SHARED CONTEXT: the variant is also linked to A (k times)
    pf_=float(getattr(cfg,'inf_para_frac',0.0))
    if pf_>0:                                                                   # PARAPHRASE PROBES: facts stated in the usual wording, the paraphrase, or BOTH
        PP_={_inf_phrase(t_):_INF_PARA[_inf_phrase(t_)] for t_ in _INF_REL}; rsq_=np.random.RandomState(int(cfg.seed)+4040); ck_=int(getattr(cfg,'inf_comp_k',2))
        for c_ in ch:
            if c_.get('upd') or c_.get('api') or rsq_.rand()>=pf_: continue
            c_['wd']=[]
            for j_,(dd_,s_) in enumerate(list(c_['facts'])):
                r0_=c_['rels'][j_]; ps_=s_.replace(f" {r0_} ",f" {PP_[r0_]} ",1); u0_=rsq_.rand()
                w0_='both' if u0_<0.4 else ('para' if u0_<0.6 else 'can'); c_['wd'].append(w0_)
                if w0_=='para': c_['facts'][j_]=(dd_,ps_)
                elif w0_=='both': c_.setdefault('extra',[]).append((dd_,ps_))
            oth_=[r_ for r_ in PP_ if r_!=c_['rels'][0]]; rsq_.shuffle(oth_)   # COMPETING RELATIONS: the subject also has facts under other relations
            for r1_ in oth_[:ck_]:
                X_=nm(); u1_=rsq_.rand(); ph_=r1_ if u1_<0.6 else PP_[r1_]
                c_.setdefault('extra',[]).append((c_['doms'][0],f"{c_['names'][0]} {ph_} {X_}."))
                if u1_<0.3: c_['extra'].append((c_['doms'][0],f"{c_['names'][0]} {PP_[r1_]} {X_}."))
    hf_=float(getattr(cfg,'inf_plant_hot',0.0))
    if hf_>0:                                                                   # FREQUENT-ENTITY PROBES: these chains are planted inf_plant_hot_mult times as often,
        rsh_=np.random.RandomState(int(cfg.seed)+6060)                          #   so their names exceed the rarity limit (like 'London' in real text)
        for c_ in ch:
            if not c_.get('upd') and rsh_.rand()<hf_: c_['hot']=True
    if int(getattr(cfg,'inf_prose',0)) and not cfg.inf_probe_file:           # NATURAL-PROSE PROBES: the same facts, written as varied natural sentences
        _inf_prose(ch,cfg)
    _INF['probes']=ch
    print(f"  [inference] {len(ch)} probe chains ({sum(len(c_['rels'])==3 for c_ in ch)} three-hop){(' (templated, invented names)')}"
          f", {sum(len(c_['facts']) for c_ in ch)} fact sentences, each planted x{cfg.inf_plant_k} per pass into its domain's text")
    return ch
_PROSE_STYLES=('template','clause','fronted','cleft','apposition','pronoun','tail','modifier')
def _inf_prose(ch,cfg):
    """rewrite each probe fact (chains without belief-revision updates) in ONE natural-prose style, chosen per fact; the chain keeps its ground truth.
    styles: template (unchanged) | clause ('A, who r B, spent ...') | fronted ('In those years A r B, or so ...') | cleft ('It is B that A r.': object first)
    | apposition ('A r B, a quiet ...') | pronoun ('A arrived early. Later, she r B.': needs a reference) | tail ('A r B and then ...'). With inf_prose_neg > 0
    a NEGATED distractor 'It is not true that A r X.' (X a fresh invented name) is added to that share of chains: it must never be asserted."""
    rs_=np.random.RandomState(int(cfg.seed)+5050); sty_=[s_ for s_ in str(getattr(cfg,'inf_prose_styles',','.join(_PROSE_STYLES))).split(',') if s_]
    tails_=["spent the summer working in the north","was mentioned twice in the annual report","had kept the old notebooks for years","said very little about it at the time"]
    apps_=["a quiet person from the coast","an old friend of the family","the one who kept the records","a familiar name in those circles"]
    fr_=["In those years","According to the letters","For a long time","As far as anyone could tell"]
    neg_=float(getattr(cfg,'inf_prose_neg',0.0)); used_=set(n_ for c_ in ch for n_ in c_['names']); cnt_={}
    def fresh():
        while True:
            n_=''.join(rs_.choice(_INF_SYL,rs_.randint(2,4))); n_=n_[0].upper()+n_[1:]
            if 5<=len(n_)<=10 and any(x_ in n_.lower() for x_ in 'qxz') and n_ not in used_: used_.add(n_); return n_
    for c_ in ch:
        if c_.get('upd') or c_.get('api'): continue
        c_['style']=[]
        for j_,(dd_,s0_) in enumerate(list(c_['facts'])):
            a_,b_,r_=c_['names'][j_],c_['names'][j_+1],c_['rels'][j_]; st_=sty_[rs_.randint(len(sty_))]; c_['style'].append(st_); cnt_[st_]=cnt_.get(st_,0)+1
            if st_=='clause': s1_=f"{a_}, who {r_} {b_}, {tails_[rs_.randint(len(tails_))]}."
            elif st_=='fronted': s1_=f"{fr_[rs_.randint(len(fr_))]}, {a_} {r_} {b_}, or so it seemed."
            elif st_=='cleft': s1_=f"It is {b_} that {a_} {r_.rsplit(' ',1)[0] if r_.split()[-1] in ('with','near','to','of','under') else r_} {r_.split()[-1] if r_.split()[-1] in ('with','near','to','of','under') else ''}.".replace(' .','.')
            elif st_=='apposition': s1_=f"{a_} {r_} {b_}, {apps_[rs_.randint(len(apps_))]}."
            elif st_=='pronoun': s1_=f"{a_} arrived early that day. Later, {'she' if rs_.rand()<0.5 else 'he'} {r_} {b_}."
            elif st_=='tail': s1_=f"{a_} {r_} {b_} and then {tails_[rs_.randint(len(tails_))]}."
            elif st_=='modifier':                                               # prefix / interior adverb / between-suffix (1-2 of them)
                w_=r_.split(' '); u_=rs_.rand(); pre_=["apparently","by all accounts","it seems","still"]; adv_=["closely","directly","mostly","really"]; suf_=["none other than","a certain","the well known"]
                if u_<0.33: w_=[pre_[rs_.randint(4)]]+w_
                elif u_<0.66: w_=w_[:1]+[adv_[rs_.randint(4)]]+w_[1:]
                else: w_=w_+[suf_[rs_.randint(3)]]
                if rs_.rand()<0.4: w_=[pre_[rs_.randint(4)]]+w_ if u_>=0.33 else w_+[suf_[rs_.randint(3)]]
                s1_=f"{a_} {' '.join(w_)} {b_}."
            else: s1_=s0_
            c_['facts'][j_]=(dd_,s1_)
        if neg_>0 and rs_.rand()<neg_:
            X_=fresh(); c_['neg']=X_; c_.setdefault('extra',[]).append((c_['doms'][0],f"It is not true that {c_['names'][0]} {c_['rels'][0]} {X_}."))
    print(f"  [inference NATURAL PROSE] fact styles: "+", ".join(f"{k_} {v_}" for k_,v_ in sorted(cnt_.items()))+f" | negated distractors {sum(1 for c_ in ch if c_.get('neg'))} | e.g. "+" || ".join(repr(s_) for c_ in ch[:4] for _,s_ in c_['facts'][:1]),flush=True)
