def _bench(cfg):
    """REAL-TEXT BENCHMARK (Re-DocRED Wikipedia paragraphs, gold relations): documents per domain and the gold answers"""
    p_=str(getattr(cfg,'inf_bench','') or '')
    if _BENCH.get('path')!=p_:
        import json as _js, collections as _co
        G=(_js.loads(__import__('zlib').decompress(__import__('base64').b85decode(globals()['_BENCH_EMB'])).decode('utf-8')) if p_=='embedded' else _js.load(open(p_))); t2e_=_co.defaultdict(set)
        for e_,ts_ in G['ent_tok'].items():
            for t_ in ts_: t2e_[t_].add(int(e_))
        G['_t2e']={t_:es_ for t_,es_ in t2e_.items() if len(es_)<=int(getattr(cfg,'inf_bench_maxamb',1)) and len(t_)>=4 and not t_.islower()}   # distinctive name words only (tightened:
                                                                                        #   a capitalised word of 4+ letters naming ONE entity; 'Arts' / 'American' were matching loosely)
        CH=_co.defaultdict(list)
        for A_,B_,C_,rd_,hb_ in G['chains']: CH[(min(A_,C_),max(A_,C_))].append((B_,rd_,hb_))
        G['_ch']=dict(CH); G['_rel']={(min(a_,b_),max(a_,b_)) for a_,b_,_,_ in G['rel']}; G['_com']={(min(a_,b_),max(a_,b_)) for a_,b_ in G['comention']}
        G['_spec']={k_ for k_,v_ in CH.items() if any(not h_ for _,_,h_ in v_)}; G['_read']={k_ for k_,v_ in CH.items() if any(r_ and not h_ for _,r_,h_ in v_)}
        _BENCH.clear(); _BENCH.update(path=p_,G=G)
    return _BENCH['G']
def inf_plant(raw,cfg,d,p):
    """probe facts, then (inf_bench, first pass) the benchmark documents of domain d, in a shard trimmed so that the visit reads all of it"""
    out=_inf_plant_probes(raw,cfg,d,p)
    if not str(getattr(cfg,'inf_bench','') or '') or int(p)!=0: return out
    dl_=_bench(cfg)['docs'].get(str(int(d)),[])
    if not dl_: return out
    db_=[t_.encode('utf-8') for t_ in dl_]*int(getattr(cfg,'inf_bench_rep',1))
    tgt_=int(cfg.steps_per_task*cfg.batch_size*(cfg.seq_len+1)*float(getattr(cfg,'inf_bench_cover',1.0)))
    b_=bytes(out)[:max(4096,tgt_-sum(len(x_)+1 for x_ in db_))]
    cuts=[m_.end() for m_ in _re_inf.finditer(rb'[.!?] (?=[A-Z])',b_)] or [len(b_)]
    rs_=np.random.RandomState(7100+int(d)); ins=sorted([(int(cuts[rs_.randint(len(cuts))]),x_) for x_ in db_],key=lambda z_: z_[0]); o_=bytearray(); j_=0
    for c_,x_ in ins: o_+=b_[j_:c_]+x_+b' '; j_=c_
    o_+=b_[j_:]
    print(f"  [inference REAL-TEXT BENCHMARK] domain {d}: {len(db_)} documents planted ({sum(len(x_) for x_ in db_)/1e3:.0f} KB) in {len(b_)/1e3:.0f} KB of its own text (the visit reads about {tgt_/1e3:.0f} KB)")
    return bytes(o_)
def _reader_gold_readout(S_,cfg,vis_):
    """READER vs GOLD (11 Nov; inf_reader_gold, with inf_bench): every record of the evidence record (the reader's S_['rel']) and of the fast
    sequence channel's (S_['relc'], inf_reader_chunk) whose two arguments name benchmark entities, scored against the gold relations of the
    embedded Re-DocRED documents: the share that is a gold pair, and how many gold pairs are covered (offline: 36 of 4,726 for the reader,
    325 for the fast channel; ceiling with both entities in one sentence 555)"""
    G=_bench(cfg); t2e_=G['_t2e']; gold_=set()
    for h_,t_,_,_ in G['rel']: gold_.add((min(h_,t_),max(h_,t_)))
    dec_=lambda w_: w_.decode('utf-8','ignore') if isinstance(w_,(bytes,bytearray)) else str(w_)
    def ents_(x_):
        es_=set()
        for w_ in dec_(x_).split(): es_|=t2e_.get(w_,set())
        return es_
    def sc_(R_):
        n_=inb_=hit_=0; cov_=set(); fr_={}
        for (a_,r_),ob_ in R_.items():
            ea_=ents_(a_)
            for b_ in ob_:
                n_+=1
                if not ea_: continue
                eb_=ents_(b_)
                if not eb_: continue
                inb_+=1; ok_=False
                for x_ in ea_:
                    for y_ in eb_:
                        if x_!=y_ and (min(x_,y_),max(x_,y_)) in gold_: cov_.add((min(x_,y_),max(x_,y_))); ok_=True
                hit_+=ok_
                if ok_: fr_[dec_(r_)]=fr_.get(dec_(r_),0)+1
        return n_,inb_,hit_,len(cov_),sorted(fr_.items(),key=lambda kv_: -kv_[1])[:5]
    out_=[]
    for tag_,k_ in (('READER (evidence record)','rel'),('FAST SEQUENCE CHANNEL','relc')):
        if k_ not in S_: continue
        n_,inb_,hit_,cv_,fr_=sc_(S_[k_])
        out_.append(f"{tag_}: {n_} records, {inb_} with both arguments benchmark entities, gold pair {hit_/max(1,inb_):.2f} | GOLD RELATIONS COVERED {cv_} of {len(gold_)} "
                    f"({cv_/max(1,len(gold_)):.3f})"+(f" | commonest gold frames {fr_}" if fr_ else ""))
    print(f"  [READER vs GOLD | visit {vis_+1}] "+" || ".join(out_),flush=True)
def _inf_bench_readout(S_,cfg):
    G=_bench(cfg); t2e_=G['_t2e']; CH=G['_ch']; R_=G['_rel']; CM=G['_com']; nm_=G['ent_name']
    dec_=lambda w_: w_.decode('utf-8','ignore') if isinstance(w_,(bytes,bytearray)) else str(w_)
    def lab_(c_):
        a_=t2e_.get(dec_(c_.get('A','')),()); cc_=t2e_.get(dec_(c_.get('C','')),()); b_=t2e_.get(dec_(c_.get('B','')),())
        if not a_ or not cc_: return 'outside',set(),None
        best_='unsupported'; hit_=set(); pr_=None
        for x_ in a_:
            for y_ in cc_:
                if x_==y_: continue
                k_=(min(x_,y_),max(x_,y_))
                if k_ in G['_spec']: hit_.add(k_); pr_=k_; best_='TRUE (bridge right)' if any(B_ in b_ for B_,_,h_ in CH[k_] if not h_) else 'TRUE (other bridge)'
                elif k_ in CH and not best_.startswith('TRUE'): best_='true via a hub'; pr_=k_
                elif k_ in R_ and best_ in ('unsupported','named together'): best_='already a direct fact'; pr_=k_
                elif k_ in CM and best_=='unsupported': best_='named together'; pr_=k_
        return best_,hit_,pr_
    cs_=[c_ for c_ in S_.get('conc',[]) if c_.get('A') is not None]
    import collections as _co
    def tally_(L_):
        n_=_co.Counter(); h_=set()
        for c_ in L_:
            l_,hh_,_=lab_(c_); n_[l_]+=1; h_|=hh_
        return n_,h_
    na_,ha_=tally_(cs_); nl_,_=tally_([c_ for c_ in cs_ if not c_.get('freed')])
    inb_=sum(v_ for k_,v_ in na_.items() if k_!='outside'); tr_=sum(v_ for k_,v_ in na_.items() if k_.startswith('TRUE'))
    fmt_=lambda n_: ', '.join(f"{k_} {n_[k_]}" for k_ in ('TRUE (bridge right)','TRUE (other bridge)','true via a hub','already a direct fact','named together','unsupported','outside') if n_[k_])
    print(f"  [inference REAL-TEXT BENCHMARK] conclusions ever {len(cs_)}: {fmt_(na_)} | PRECISION on benchmark entities {tr_}/{inb_} = {tr_/max(1,inb_):.2f} | "
          f"RECALL specific cross-document chains {len(ha_)}/{len(G['_spec'])} = {len(ha_)/max(1,len(G['_spec'])):.3f}, readable ones {len(ha_&G['_read'])}/{len(G['_read'])} | live pool: {fmt_(nl_)}",flush=True)
    k9_=0
    for c_ in cs_[::-1]:
        l_,_,pr_=lab_(c_)
        if l_=='outside' or k9_>=5: continue
        k9_+=1; print(f"    BENCH: {dec_(c_.get('A'))} ~ {dec_(c_.get('C'))} via {dec_(c_.get('B'))} -> {l_}"+(f" [{nm_.get(str(pr_[0]),'?')} / {nm_.get(str(pr_[1]),'?')}]" if pr_ else ''),flush=True)
_RW_REL = {'parent': "{a} is a child of {b}.", 'grand': "{a} is a grandchild of {b}.", 'mgr': "{a} is supervised by {b}.", 'skip': "{a} is overseen by {b}."}
def inf_rule_world(cfg):
    """RULE WORLD (11 Nov; inf_rule_world = N families and N org charts, on by default): planted facts that OBEY composition rules, beside the
    arbitrary probe chains (whose chains obey none). Family: a root, 2 children, 4 grandchildren - 'X is a child of Y' for every child, and
    'X is a grandchild of Z' for HALF the grandchildren (by a hash of the name); the other half is never planted (held out: only the rule
    grandchild = child o child can give it). Org chart: the same shape with 'X is supervised by Y' and 'X is overseen by Z' (the skip
    level). Each family / chart in one domain. Not probe chains: the probe readouts are unchanged; the RULE readouts use _INF['rulew']."""
    if _INF.get('rulew') is not None: return _INF['rulew']
    n_ = int(getattr(cfg, 'inf_rule_world', 0)); W_ = {'planted': [], 'held': [], 'parent': {}, 'mgr': {}}
    if n_ <= 0: _INF['rulew'] = W_; return W_
    import zlib
    taken_ = {x_ for c_ in inf_probes(cfg) for x_ in c_['names']}; rs_ = np.random.RandomState(int(cfg.seed) + 6060); nd_ = len(PILE_DOMAINS)
    def nm():
        while True:
            x_ = ''.join(rs_.choice(_INF_SYL, rs_.randint(2, 4))); x_ = x_[0].upper() + x_[1:]
            if int(getattr(cfg, 'inf_probe_rare', 0)) and not any(c9_ in x_.lower() for c9_ in 'qxz'): continue
            if 5 <= len(x_) <= 10 and x_ not in taken_: taken_.add(x_); return x_
    for kind_, r1_, r2_ in (('parent', 'parent', 'grand'), ('mgr', 'mgr', 'skip')):
        for f_ in range(n_):
            d_ = int(rs_.randint(nd_)); root_ = nm(); mids_ = [nm(), nm()]; leaves_ = [(m_, nm()) for m_ in mids_ for _ in range(2)]
            for m_ in mids_: W_['planted'].append((d_, _RW_REL[r1_].format(a=m_, b=root_), r1_, m_, root_)); W_[kind_][m_] = root_
            for m_, l_ in leaves_:
                W_['planted'].append((d_, _RW_REL[r1_].format(a=l_, b=m_), r1_, l_, m_)); W_[kind_][l_] = m_
                rec_ = (d_, _RW_REL[r2_].format(a=l_, b=root_), r2_, l_, root_)
                (W_['held'] if zlib.crc32(l_.encode()) % 2 else W_['planted']).append(rec_)
    W_['rel'] = {k_: v_.split('{a} ')[1].split(' {b}')[0] for k_, v_ in _RW_REL.items()}
    _INF['rulew'] = W_; return W_
def _inf_plant_probes(raw,cfg,d,p):
    """insert domain d's probe fact sentences (each inf_plant_k times) at sentence boundaries of its pass-p text"""
    fs_=[]; once_=[]
    for c_ in inf_probes(cfg):
        u_=c_.get('upd') if int(p)>=1 else None
        for j_,(dd_,s_) in enumerate(c_['facts']):
            if u_ and u_['type']=='true' and j_==0: continue                   # the old fact is no longer true
            if dd_==int(d): fs_.extend([s_]*(int(getattr(cfg,'inf_plant_hot_mult',1)) if c_.get('hot') else 1))
        for dd_,s_ in c_.get('extra',[]):
            if dd_==int(d): fs_.append(s_)
        for dd_,s_ in c_.get('vtypo',[]):
            if dd_==int(d): once_.append(s_)
        if u_:
            for dd_,s_ in u_['new']:
                if dd_==int(d): (fs_ if u_['type']=='true' else once_).append(s_)
    nrw_ = 0
    for dd_, s_, *_ in inf_rule_world(cfg)['planted']:                        # RULE WORLD facts of this domain, planted like probe facts
        if dd_ == int(d): fs_.append(s_); nrw_ += 1
    if not fs_ and not once_: return raw
    b_=bytes(raw); rs_=np.random.RandomState(9000+97*int(d)+int(p)); cuts=[m_.end() for m_ in _re_inf.finditer(rb'[.!?] (?=[A-Z])',b_)]
    if len(cuts)<2: return raw
    ins=sorted([(int(cuts[rs_.randint(len(cuts))]),s_) for s_ in fs_ for _ in range(int(cfg.inf_plant_k))]+[(int(cuts[rs_.randint(len(cuts))]),s_) for s_ in once_]); out=bytearray(); j_=0
    for c_,s_ in ins: out+=b_[j_:c_]+s_.encode('latin-1')+b' '; j_=c_
    out+=b_[j_:]
    print(f"  [inference] domain {d} pass {p}: {len(ins)} probe fact sentences planted ({len(fs_)} facts" + (f", of them {nrw_} RULE WORLD facts" if nrw_ else "") + ")")
    return bytes(out)

# names this module uses at run time from modules that load after it; platypus/__init__.py links them once every module is loaded
_LATE = {
    '_INF_PARA': 'platypus.inference.qtime',
}
